 function calcVirtualFtReserve(uint32 lsf, uint256 ftReserve) internal pure returns (uint256 virtualFtReserve) {
        virtualFtReserve = (ftReserve * Constants.DECIMAL_BASE) / lsf;
 if (virtualFtReserve == 0) {
