As you can see from the error logs, the transaction failed with an error message:
panic code 0x11 (Arithmetic operation overflowed outside of an unchecked block)
. And the problem was not the use of a buggy
Statistics.sol
library, but the logic behind the score range calculation in
LLMOracleCoordinator::finalizeValidation
.
Impact
Tasks with scores causing
_mean < _stddev
cannot complete, leading to a halt in the validation process and blocking reward distribution. Since scores submitted by prior validators to the
TaskValidation
struct array are immutable, tasks may become permanently locked in
PendingValidation
status, posing a potential DoS vulnerability.
Tools Used
Manual Code Review, Remix, Hardhat
Recommendations
LLMOracleCoordinator::finalizeValidation
needs to be refactored. You could think about rewriting both underflow-prone conditions in
finalizeValidation
using only addition operations, adjusting the logic to avoid subtraction:
----new code block----
​
for (uint256 v_i = 0; v_i < task.parameters.numValidations; ++v_i) {
    uint256 score = scores[v_i];
-    if ((score >= _mean - _stddev) && (score <= _mean + _stddev)) {
+    if ((score + _stddev >= _mean) && (score <= _mean + _stddev))
        innerSum += score;
        innerCount++;
​
        _increaseAllowance(validations[taskId][v_i].validator, task.validatorFee);
        }
    }
    ........
    ........
for (uint256 g_i = 0; g_i < task.parameters.numGenerations; g_i++) {
    // ignore lower outliers
-    if (generationScores[g_i] >= mean - generationDeviationFactor * stddev) {
+    if (generationScores[g_i] + generationDeviationFactor * stddev >= mean)    
        _increaseAllowance(responses[taskId][g_i].responder, task.generatorFee);
    }
}
----end of code block ----
After applying the suggested fixes, the issues are mitigated. Adjust the last line in the PoC to
expect(finalRequest.status).to.equal(TaskStatus.Completed);
and run the test with
yarn test ./test/LLMOracleCoordinator.test.ts
, it will pass.

https://solodit.cyfrin.io/issues/inaccur.audit_content:
Inaccurate best response selection in
LLMOracleCoordinator::getBestResponse
.
Severity
Medium Risk
Summary
The
LLMOracleCoordinator::getBestResponse
function may not return the best performing result of the given task. This behaviour can lead to less than optimal purchases, especially in scenarios where response validation has not taken place.
Description
The
LLMOracleCoordinator::getBestResponse
function aims to return the best-performing response based on validation scores for a given task. However, there is an issue when the task responses have no validation requirements, as it is when
task.parameters.numValidations == 0
in
LLMOracleCoordinator::respond
. In such cases, all responses will be assigned a default score of 0 (see [
https://github.com/Cyfrin/2024-10-swan-dria/blob/main/contracts/llm/LLMOracleCoordinator.sol#L226
]) and will not require any validation, setting the task status to
Completed
. This may lead to the following consequences:
** The
LLMOracleCoordinator::getBestResponse
function selects the first response from
taskResponses
array, which may not represent the best or most accurate result. In fact it could be an empty, irrelevant or false response. Since all scores are 0, this does not indicate performance quality.
----new code block----
function getBestResponse(uint256 taskId) external view returns (TaskResponse memory) {
 TaskResponse[] storage taskResponses = responses[taskId];
​
 if (requests[taskId].status != LLMOracleTask.TaskStatus.Completed) {
            revert InvalidTaskStatus(taskId, requests[taskId].status, LLMOracleTask.TaskStatus.Completed);
        }
​
@>        TaskResponse storage result = taskResponses[0];
@>        uint256 highestScore = result.score;
 for (uint256 i = 1; i < taskResponses.length; i++) {
@>            if (taskResponses[i].score > highestScore) { 
                highestScore = taskResponses[i].score;
                result = taskResponses[i];
            }
        }
 return result;}
----end of code block ----
** When the task parameter
numValidations
is set to 0, the system lacks a mechanism to validate responses effectively. Consequently, even incorrect or irrelevant responses can be treated as acceptable output and returned as the best result after calling
LLMOracleCoordinator::getBestResponse
.
PoC
For the proof of concept here is a valid test case, please paste it into the
LLMOracleCoordinator.test.ts
file:
----new code block----
describe("without validation", function () {
 const [numGenerations, numValidations] = [2, 0];
 let generatorAllowancesBefore: bigint[];
​
 this.beforeAll(async () => {
      taskId++;
      generatorAllowancesBefore = await Promise.all(
        generators.map((g) => token.allowance(coordinatorAddress, g.address))
      );
    });
​
 it("should make a request", async function () {
 await safeRequest(coordinator, token, requester, taskId, input, models, {
        difficulty,
        numGenerations,
        numValidations,
      });
    });
​
 it("should NOT respond if not a registered Oracle", async function () {
 const generator = dummy;
​
 await expect(safeRespond(coordinator, generator, output, metadata, taskId, 0n))
        .to.revertedWithCustomError(coordinator, "NotRegistered")
        .withArgs(generator.address);
    });
​
 it("should respond (1/2) to a request only once", async function () {
 // using the first generator
 const generator = generators[0];
 await safeRespond(coordinator, generator, output, metadata, taskId, 0n);
​
 // should NOT respond again
 await expect(safeRespond(coordinator, generator, output, metadata, taskId, 0n))
        .to.be.revertedWithCustomError(coordinator, "AlreadyResponded")
        .withArgs(taskId, generator.address);
    });
​
 it("should respond (2/2)", async function () {
 // use the second generator
 const generator = generators[1];
 await safeRespond(coordinator, generator, output, metadata, taskId, 1n);
    });
​
 it("should NOT respond if task is not pending generation", async function () {
 // this time we use the other generator
 const generator = generators[2];
​
 await expect(safeRespond(coordinator, generator, output, metadata, taskId, 2n))
        .to.revertedWithCustomError(coordinator, "InvalidTaskStatus")
        .withArgs(taskId, TaskStatus.Completed, TaskStatus.PendingGeneration);
    });
​
 it("should NOT respond to a non-existent request", async function () {
 const generator = generators[0];
 const nonExistentTaskId = 999n;
​
 await expect(safeRespond(coordinator, generator, output, metadata, nonExistentTaskId, 0n))
        .to.revertedWithCustomError(coordinator, "InvalidTaskStatus")
        .withArgs(nonExistentTaskId, TaskStatus.None, TaskStatus.PendingGeneration);
    });
​
 // Test case returns the very first response when no validations are present
 it("should return the first response as the 'best' when no validations are present", async function () {

 const task = await coordinator.requests(taskId);
 console.log(`Task Status: ${task.status}`);
 expect(task.status).to.equal(TaskStatus.Completed);

 const responses = await coordinator.getResponses(taskId);
 console.log("Generator responses:");
      responses.forEach((response: any, index: number) => {
 console.log(`  Generator ${index} Address: ${response.responder}, Score: ${response.score}`);
      });

 const bestResponse = await coordinator.getBestResponse(taskId);
 console.log(`Best Response - Responder: ${bestResponse.responder}, Score: ${bestResponse.score}`);

 expect(bestResponse.responder).to.equal(generators[0].address);
 expect(bestResponse.score).to.equal(0); 
    });
​
 it("should see rewards", async function () {
 const task = await coordinator.requests(taskId);
​
 for (let i = 0; i < numGenerations; i++) {
 const allowance = await token.allowance(coordinatorAddress, generators[i].address);
 expect(allowance - generatorAllowancesBefore[i]).to.equal(task.generatorFee);
      }
    });
  });
----end of code block ----
The test can be run with
yarn test ./test/LLMOracleCoordinator.test.ts --verbose
.
Here are the logs:
----new code block----
Task Status: 3
Generator responses:
 Generator 0 Address: 0x90F79bf6EB2c4f870365E785982E1f101E93b906, Score: 0
 Generator 1 Address: 0x15d34AAf54267DB7D7c367839AAf71A00a2C6A65, Score: 0
Best Response - Responder: 0x90F79bf6EB2c4f870365E785982E1f101E93b906, Score: 0
----end of code block ----
As you can see from the error logs, if oracle response validation is not required, all generated responses get the default score of 0 and the
LLMOracleCoordinator::getBestResponse
function returns the very first result pushed into the
TaskResponse
array of structs.
Impact
A core
BuyerAgent::purchase
function relies on the results of the
LLMOracleCoordinator::getBestResponse
function, which may not reflect the response quality or relevance, resulting in purchases based on inaccurate information. If users consistently receive from oracles poor answers that are labelled as the best, this would lead to financial losses as users would not purchase the best items, resulting in frustration and reduced confidence in the system's capabilities.
Tools Used
Manual Code Review, Hardhat
Recommendations
Consider introducing a threshold for the number of validations required before considering any response valid. It can be set in
LLMOracleManager.sol
. This ensures that responses are subjected to some level of scrutiny before being considered for the best-performing result.
Revise the logic in the
getBestResponse
function to ensure that it only selects responses with non-zero scores. If all responses have a score of 0, the function should revert with a clear message indicating that no valid responses were found, or return a designated fallback value that signifies the absence of a suitable response.

https://solodit.cyfrin.io/issues/m-02-in.audit_content:
Users can call
PositionAction::decreaseLever
through a proxy, to "Decrease the leverage of a position by taking out a credit flash loan to withdraw and sell collateral". After it is called, the flash loan lender sends the credit and calls
onCreditFlashLoan
, which handles all that logic. When doing so, users are supposed to swap their collateral withdrawn into debt tokens so that the flash loan can be repaid.
The protocol tries to handle the residual amount from the swap (
swapped - paid debt
), by trying to repay extra debt for the designated position, using:
----new code block----
if (residualAmount > 0) {
    underlyingToken.forceApprove(address(leverParams.vault), residualAmount);
    ICDPVault(leverParams.vault).modifyCollateralAndDebt(
        leverParams.position,
 address(this),
 address(this),
 0,
 -toInt256(residualAmount)
    );
}
----end of code block ----
However, this is invalid for 2 main reasons:
This is trying to repay extra debt than what the user is trying to, which is passed in the
primarySwap.amount
.
If the user tries to repay his whole debt using
decreaseLever
the TX will revert, as it'll try to repay some nonexistent debt.
Proof of Concept
Add the following test in
src/test/integration/PositionAction20.lever.t.sol
:
----new code block----
function test_leverageDownWrongResidualHandling() public {
 uint256 depositAmount = 1_000 ether;
 uint256 borrowAmount = 200 ether;
​
    deal(address(token), user, depositAmount);
​
 address[] memory assets = new address[](2);
    assets[0] = address(token);
    assets[1] = address(underlyingToken);
​
    vm.startPrank(user);
​
 // User deposits 1k ETH collateral
    token.approve(address(vault), type(uint256).max);
    vault.deposit(address(userProxy), depositAmount);
​
 // User borrows 200 ETH
    userProxy.execute(
 address(positionAction),
 abi.encodeWithSelector(
            positionAction.borrow.selector,
 address(userProxy),
 address(vault),
            CreditParams({amount: borrowAmount, creditor: user, auxSwap: emptySwap})
        )
    );
​
    userProxy.execute(
 address(positionAction),
 abi.encodeWithSelector(
            positionAction.decreaseLever.selector,
            LeverParams({
                position: address(userProxy),
                vault: address(vault),
                collateralToken: address(token),
                primarySwap: SwapParams({
                    swapProtocol: SwapProtocol.BALANCER,
                    swapType: SwapType.EXACT_IN,
                    assetIn: address(token),
                    amount: vault.virtualDebt(address(userProxy)),
                    limit: 0,
                    recipient: address(positionAction),
                    residualRecipient: address(positionAction),
                    deadline: block.timestamp,
                    args: abi.encode(weightedPoolIdArray, assets)
                }),
                auxSwap: emptySwap,
                auxAction: emptyPoolActionParams
            }),
 201 ether,
 address(userProxy)
        )
    );
​
    vm.stopPrank();
}
----end of code block ----
Logs:
